1	/**
2	 * Scoped to this molecule's own contract per testing.md: the AC-1/AC-5 branch logic and the
3	 * roving-tabindex invariant that this component alone is responsible for proving. Keyboard-focus
4	 * movement and pagination-window interaction are exercised in index.stories.tsx's `play`
5	 * functions instead — both are "user-facing interaction in a single component," which
6	 * testing.md routes to Storybook `play`, not Vitest.
7	 *
8	 * ZimmColourSwatch is left real (not mocked): composition is part of the contract under test —
9	 * this suite proves how many colours the molecule chooses to render and which one it marks
10	 * selected, not how a swatch itself looks (that is ZimmColourSwatch's own suite's job).
11	 *
12	 * Every render is wrapped three ways:
13	 *   - `ChakraProvider theme={theme}` — the real theme, not Chakra's default. Without it,
14	 *     `useMultiStyleConfig` for both this recipe and the atom's own resolve against a theme with
15	 *     no such keys registered — same reasoning as zimmProductMeta/index.test.tsx's own note.
16	 *   - `MemoryRouter` — ZimmColourSwatch can render a react-router `Link`, which throws outside one.
17	 *   - `IntlProvider` — this component calls `useIntl()` directly, which throws outside one
18	 *     (react-intl's `invariantIntlContext`).
19	 *
20	 * ZimmIcon is mocked at the smallest surface — the known, documented Vitest gap (it pulls in the
21	 * base SFCC icons barrel, which has a top-level side effect that fails under Vitest's SVG
22	 * transform; see testing.md). Mocked via the same relative specifier index.tsx itself imports,
23	 * so there is no cross-specifier module-resolution question to reason about.
24	 */
25	import React from 'react';
26	import { describe, test, expect, vi } from 'vitest';
27	import { render, screen } from '@testing-library/react';
28	import { ChakraProvider } from '@chakra-ui/react';
29	import { MemoryRouter } from 'react-router-dom';
30	import { IntlProvider } from 'react-intl';
31	import theme from 'app/theme';
32	import { ZimmColourSwatchGroup } from './index';
33	import type { ZimmColourSwatchValue } from './index';
34	
35	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
36	
37	const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;
38	
39	const BAY_BLUE: ZimmColourSwatchValue = {
40	  value: 'BAYBL',
41	  name: 'Bay Blue',
42	  href: '/p.html?color=BAYBL',
43	  imageUrl: IMAGE('bay-blue'),
44	};
45	const IVORY: ZimmColourSwatchValue = {
46	  value: 'IVORY',
47	  name: 'Ivory',
48	  href: '/p.html?color=IVORY',
49	  imageUrl: IMAGE('ivory'),
50	};
51	const BLACK: ZimmColourSwatchValue = {
52	  value: 'BLACK',
53	  name: 'Black',
54	  href: '/p.html?color=BLACK',
55	  imageUrl: IMAGE('black'),
56	};
57	/** No `imageUrl` — exercises AC 5's filter. */
58	const ROSE_UNPOPULATED: ZimmColourSwatchValue = { value: 'ROSE', name: 'Rose Pink', href: '/p.html?color=ROSE' };
59	const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };
60	
61	const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
62	  render(
63	    <ChakraProvider theme={theme}>
64	      <IntlProvider locale="en-AU" defaultLocale="en-AU">
65	        <MemoryRouter>
66	          <ZimmColourSwatchGroup label="Colour" values={[BAY_BLUE, IVORY, BLACK]} {...props} />
67	        </MemoryRouter>
68	      </IntlProvider>
69	    </ChakraProvider>,
70	  );
71	
72	describe('ZimmColourSwatchGroup', () => {
73	  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
74	    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });
75	    expect(screen.queryAllByRole('radio')).toHaveLength(0);
76	    expect(screen.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
77	  });
78	
79	  test('renders one radio swatch per populated colour', () => {
80	    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
81	    expect(screen.getAllByRole('radio')).toHaveLength(3);
82	  });
83	
84	  test('marks exactly the swatch matching selectedValue as checked', () => {
85	    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
86	    const checked = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('aria-checked') === 'true');
87	    expect(checked).toHaveLength(1);
88	    expect(checked[0]).toHaveAccessibleName('Ivory');
89	  });
90	
91	  test('AC 5: filters out colours whose index image is not populated', () => {
92	    const { container } = renderGroup({ values: [BAY_BLUE, IVORY, BLACK, ROSE_UNPOPULATED, GOLD_UNPOPULATED] });
93	    expect(screen.getAllByRole('radio')).toHaveLength(3);
