 * Scoped to this molecule's own contract per testing.md: the AC-1/AC-5 branch logic and the
 * roving-tabindex invariant that this component alone is responsible for proving. Keyboard-focus
 * movement and pagination-window interaction are exercised in index.stories.tsx's `play`
 * functions instead — both are "user-facing interaction in a single component," which
 * testing.md routes to Storybook `play`, not Vitest.
 *
 * ZimmColourSwatch is left real (not mocked): composition is part of the contract under test —
 * this suite proves how many colours the molecule chooses to render and which one it marks
 * selected, not how a swatch itself looks (that is ZimmColourSwatch's own suite's job).
 *
 * Every render is wrapped three ways:
 *   - `ChakraProvider theme={theme}` — the real theme, not Chakra's default. Without it,
 *     `useMultiStyleConfig` for both this recipe and the atom's own resolve against a theme with
 *     no such keys registered — same reasoning as zimmProductMeta/index.test.tsx's own note.
 *   - `MemoryRouter` — ZimmColourSwatch can render a react-router `Link`, which throws outside one.
 *   - `IntlProvider` — this component calls `useIntl()` directly, which throws outside one
 *     (react-intl's `invariantIntlContext`).
 *
 * ZimmIcon is mocked at the smallest surface — the known, documented Vitest gap (it pulls in the
 * base SFCC icons barrel, which has a top-level side effect that fails under Vitest's SVG
 * transform; see testing.md). Mocked via the same relative specifier index.tsx itself imports,
 * so there is no cross-specifier module-resolution question to reason about.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;

const BAY_BLUE: ZimmColourSwatchValue = {
  value: 'BAYBL',
  name: 'Bay Blue',
  href: '/p.html?color=BAYBL',
  imageUrl: IMAGE('bay-blue'),
};
const IVORY: ZimmColourSwatchValue = {
  value: 'IVORY',
  name: 'Ivory',
  href: '/p.html?color=IVORY',
  imageUrl: IMAGE('ivory'),
};
const BLACK: ZimmColourSwatchValue = {
  value: 'BLACK',
  name: 'Black',
  href: '/p.html?color=BLACK',
  imageUrl: IMAGE('black'),
};
/** No `imageUrl` — exercises AC 5's filter. */
const ROSE_UNPOPULATED: ZimmColourSwatchValue = { value: 'ROSE', name: 'Rose Pink', href: '/p.html?color=ROSE' };
const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={[BAY_BLUE, IVORY, BLACK]} {...props} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('ZimmColourSwatchGroup', () => {
  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
    expect(screen.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
  });

  test('renders one radio swatch per populated colour', () => {
    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
  });

  test('marks exactly the swatch matching selectedValue as checked', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const checked = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('aria-checked') === 'true');
    expect(checked).toHaveLength(1);
    expect(checked[0]).toHaveAccessibleName('Ivory');
  });

  test('AC 5: filters out colours whose index image is not populated', () => {
    const { container } = renderGroup({ values: [BAY_BLUE, IVORY, BLACK, ROSE_UNPOPULATED, GOLD_UNPOPULATED] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
    expect(container.textContent).not.toContain('Rose Pink');
    expect(container.textContent).not.toContain('Gold');
  });

  test('AC 5 filters on image population only, never a stock/orderability-like field', () => {
    // This component's own prop type carries no stock field at all — the extra property below
    // proves the filter cannot be keying on one, since there is nowhere in the type for it to
    // come from other than this deliberately-bolted-on test fixture.
    const valueWithExtraField: ZimmColourSwatchValue & { orderable: boolean } = { ...BAY_BLUE, orderable: false };
    renderGroup({ values: [valueWithExtraField, IVORY] });
    expect(screen.getByRole('radio', { name: 'Bay Blue' })).toBeInTheDocument();
  });

  test('collapses to the label-only branch when only one of several colours is populated', () => {
    renderGroup({
      selectedName: 'Bay Blue',
      selectedValue: 'BAYBL',
      values: [BAY_BLUE, ROSE_UNPOPULATED, GOLD_UNPOPULATED],
    });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });

  test('keeps exactly one swatch in the roving tab order at a time', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const tabbable = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('tabindex') === '0');
    expect(tabbable).toHaveLength(1);
  });

  test('resolves its recipe under a ChakraProvider — registered, not silently inherited', () => {
    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
    // The only detection anywhere for this recipe losing its entry in theme/components/index.ts
    // — same reasoning as zimmProductMeta/index.test.tsx's own equivalent test. Measured as the
    // literal var() declaration, not a resolved px value: jsdom's getComputedStyle does not
    // substitute a custom property (see zimmColourSwatch/index.test.tsx's own note on this).
    const styles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
    expect(styles.gap).toBe('var(--zimm-scale-xs)');
  });

  test('mounts directly on the page containing the actual selection, not always page 1 (pagination regression)', () => {
    // 6 populated colours, selection is the 6th (index 5) — beyond the first 4-wide page. Before
    // the fix, `pageStart` always started at 0 regardless of where the selection sat, so this
    // exact shape rendered page 1 (indices 0-3) with zero items aria-checked and zero items
    // tabbable, since the selected colour was never part of the rendered window.
    const SIXTH_COLOUR: ZimmColourSwatchValue = {
      value: 'NAVY',
      name: 'Navy',
      href: '/p.html?color=NAVY',
      imageUrl: IMAGE('navy'),
    };
    const sixColours: ZimmColourSwatchValue[] = [
      BAY_BLUE,
      IVORY,
      BLACK,
      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
      SIXTH_COLOUR,
    ];

    // No interaction of any kind above this line — this asserts the component's very first render.
    renderGroup({ selectedName: SIXTH_COLOUR.name, selectedValue: SIXTH_COLOUR.value, values: sixColours });

    const radios = screen.getAllByRole('radio');
    const checkedRadios = radios.filter((radio) => radio.getAttribute('aria-checked') === 'true');
    const tabbableRadios = radios.filter((radio) => radio.getAttribute('tabindex') === '0');

    expect(checkedRadios).toHaveLength(1);
    expect(checkedRadios[0]).toHaveAttribute('aria-checked', 'true');
    expect(checkedRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);

    expect(tabbableRadios).toHaveLength(1);
    expect(tabbableRadios[0]).toHaveAttribute('tabindex', '0');
    expect(tabbableRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);
  });

  test('truncates a long selected colour name, and only the dynamic name — never the static "Colour:" label', () => {
    // 70 characters — well past anything the labelName column could render on one line, so this
    // is a real exercise of the Figma interaction annotation ("If Label/Colour name is longer,
    // use truncation"), not just a token-presence check.
    const LONG_NAME = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
    expect(LONG_NAME.length).toBeGreaterThan(60);

    renderGroup({ selectedName: LONG_NAME, selectedValue: 'BAYBL' });

    const dynamicNameStyles = window.getComputedStyle(screen.getByText(LONG_NAME));
    expect(dynamicNameStyles.overflow).toBe('hidden');
    expect(dynamicNameStyles.textOverflow).toBe('ellipsis');
    expect(dynamicNameStyles.whiteSpace).toBe('nowrap');

    // The static "Colour:" text beside it is never meant to truncate — only the dynamic name
    // carries the Figma-mandated behaviour above.
    const staticLabelStyles = window.getComputedStyle(screen.getByText('Colour:'));
    expect(staticLabelStyles.textOverflow).not.toBe('ellipsis');
  });
});

